-- Align deal finance/shipping snapshot with invoice and shipment systems of record.
create or replace function public.deal_account_snapshot_v1(p_deal_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare v_shipments int;v_active_shipments int;v_delivered int;v_invoices int;v_open_invoices int;v_receivable numeric;v_paid_cash numeric;v_paid_invoice_value numeric;v_partial_invoice_count int;v_events int;v_payment_state text;v_shipping_state text;begin if not exists(select 1 from public.deals where id=p_deal_id) then raise exception 'Deal not found.';end if;select count(*),count(*) filter(where status::text not in ('delivered','cancelled')),count(*) filter(where status::text='delivered') into v_shipments,v_active_shipments,v_delivered from public.shipments where deal_id=p_deal_id;select count(*) filter(where invoice_type='receivable' and status<>'cancelled'),count(*) filter(where invoice_type='receivable' and status not in ('paid','cancelled')),coalesce(sum(total_amount) filter(where invoice_type='receivable' and status<>'cancelled'),0),coalesce(sum(total_amount) filter(where invoice_type='receivable' and status='paid'),0),count(*) filter(where invoice_type='receivable' and status='partially_paid') into v_invoices,v_open_invoices,v_receivable,v_paid_invoice_value,v_partial_invoice_count from public.invoices where deal_id=p_deal_id;select coalesce(sum(amount),0) into v_paid_cash from public.payments where deal_id=p_deal_id and payment_type='receipt' and status='completed';select count(*) into v_events from public.deal_events where deal_id=p_deal_id;v_payment_state:=case when v_invoices=0 then 'Not Invoiced' when v_open_invoices=0 then 'Paid' when v_partial_invoice_count>0 or v_paid_cash>0 or v_paid_invoice_value>0 then 'Partial' else 'Pending' end;v_shipping_state:=case when v_shipments=0 then 'Planning' when v_active_shipments=0 and v_delivered>0 then 'Delivered' when exists(select 1 from public.shipments where deal_id=p_deal_id and status::text='customs') then 'Customs' when exists(select 1 from public.shipments where deal_id=p_deal_id and status::text='in_transit') then 'In Transit' when exists(select 1 from public.shipments where deal_id=p_deal_id and status::text='picked_up') then 'Picked Up' else 'Booked / Planning' end;return jsonb_build_object('shipments',v_shipments,'active_shipments',v_active_shipments,'delivered_shipments',v_delivered,'invoices',v_invoices,'open_invoices',v_open_invoices,'receivable_value',v_receivable,'paid_invoice_value',v_paid_invoice_value,'cash_receipts',v_paid_cash,'payment_state',v_payment_state,'shipping_state',v_shipping_state,'events',v_events);end$$;
revoke all on function public.deal_account_snapshot_v1(uuid) from public,anon;grant execute on function public.deal_account_snapshot_v1(uuid) to authenticated,service_role;
